import { Component, OnInit, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { MatIconModule } from '@angular/material/icon';
import { AuthService } from '../../core/auth.service';

type Step = 'email' | 'create-code' | 'confirm-code' | 'enter-code';

const CODE_LENGTH = 6;
const LAST_EMAIL_KEY = 'note-course.lastEmail';

@Component({
  selector: 'app-login',
  imports: [FormsModule, MatIconModule],
  templateUrl: './login.html',
  styleUrl: './login.scss',
})
export class Login implements OnInit {
  step = signal<Step>('email');
  email = '';
  code = signal('');

  // Dernier email utilisé, mémorisé localement pour éviter de le retaper à
  // chaque ouverture de l'app ; "Changer de compte" repasse en saisie libre.
  savedEmail = signal<string | null>(localStorage.getItem(LAST_EMAIL_KEY));
  useSavedAccount = signal(this.savedEmail() !== null);

  // true quand l'utilisateur vient de se connecter avec le code provisoire
  // ("code oublié") et doit obligatoirement en définir un nouveau.
  resetMode = signal(false);

  private pendingNewCode = '';

  loading = signal(false);
  errorMessage = signal('');
  infoMessage = signal('');

  readonly codeDots = Array.from({ length: CODE_LENGTH });

  constructor(private auth: AuthService, private router: Router) {}

  ngOnInit(): void {
    // Session issue d'un "code oublié" jamais finalisée (ex. page rechargée) :
    // on renvoie directement à la création du nouveau code, sans repasser par l'email.
    const user = this.auth.user();
    if (user?.mustResetCode) {
      this.email = user.email;
      this.resetMode.set(true);
      this.step.set('create-code');
    }
  }

  get emailValid(): boolean {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(this.email.trim());
  }

  get codeTitle(): string {
    switch (this.step()) {
      case 'create-code':
        return this.resetMode() ? 'Définissez un nouveau code' : 'Créez votre code';
      case 'confirm-code':
        return this.resetMode() ? 'Confirmez le nouveau code' : 'Confirmez votre code';
      default:
        return 'Entrez votre code';
    }
  }

  get codeHint(): string {
    if (this.step() === 'create-code') {
      return this.resetMode()
        ? 'Ce nouveau code à 6 chiffres remplacera le code provisoire.'
        : 'Ce code à 6 chiffres vous servira à vous connecter.';
    }
    if (this.step() === 'confirm-code') {
      return 'Ressaisissez le même code.';
    }
    return 'Bon retour !';
  }

  continueWithSavedEmail(): void {
    const email = this.savedEmail();
    if (!email) return;
    this.email = email;
    this.submitEmail();
  }

  switchAccount(): void {
    this.useSavedAccount.set(false);
    this.email = '';
    this.errorMessage.set('');
  }

  submitEmail(): void {
    if (!this.emailValid || this.loading()) return;

    this.loading.set(true);
    this.errorMessage.set('');
    this.infoMessage.set('');

    const email = this.email.trim();
    this.auth.checkEmail(email).subscribe({
      next: ({ exists }) => {
        this.loading.set(false);
        this.code.set('');
        this.rememberEmail(email);
        this.step.set(exists ? 'enter-code' : 'create-code');
      },
      error: () => {
        this.loading.set(false);
        this.errorMessage.set('Impossible de vérifier cet email pour le moment.');
      },
    });
  }

  private rememberEmail(email: string): void {
    localStorage.setItem(LAST_EMAIL_KEY, email);
    this.savedEmail.set(email);
  }

  backToEmail(): void {
    if (this.resetMode()) {
      // Session provisoire abandonnée : on ne laisse pas un compte à moitié
      // réinitialisé traîner en session.
      this.auth.logout();
    }
    this.resetMode.set(false);
    this.step.set('email');
    this.code.set('');
    this.errorMessage.set('');
    this.infoMessage.set('');
  }

  tapDigit(digit: string): void {
    if (this.code().length >= CODE_LENGTH || this.loading()) return;
    this.errorMessage.set('');
    this.code.set(this.code() + digit);

    if (this.code().length === CODE_LENGTH) {
      this.onCodeComplete();
    }
  }

  backspace(): void {
    this.code.set(this.code().slice(0, -1));
  }

  private onCodeComplete(): void {
    const step = this.step();
    if (step === 'create-code') {
      this.pendingNewCode = this.code();
      this.code.set('');
      this.step.set('confirm-code');
    } else if (step === 'confirm-code') {
      if (this.code() === this.pendingNewCode) {
        if (this.resetMode()) {
          this.finishSetCode(this.pendingNewCode);
        } else {
          this.finishRegister(this.pendingNewCode);
        }
      } else {
        this.errorMessage.set('Les deux codes ne correspondent pas, recommencez.');
        this.pendingNewCode = '';
        this.code.set('');
        this.step.set('create-code');
      }
    } else if (step === 'enter-code') {
      this.submitLogin();
    }
  }

  private finishRegister(code: string): void {
    this.loading.set(true);
    this.auth.register(this.email.trim(), code).subscribe({
      next: () => {
        this.loading.set(false);
        this.router.navigate(['/home']);
      },
      error: (err) => {
        this.loading.set(false);
        this.code.set('');
        this.step.set('create-code');
        this.errorMessage.set(
          err.status === 409
            ? 'Un compte existe déjà avec cet email.'
            : 'Impossible de créer le compte pour le moment.'
        );
      },
    });
  }

  private finishSetCode(code: string): void {
    this.loading.set(true);
    this.auth.setCode(code).subscribe({
      next: () => {
        this.loading.set(false);
        this.resetMode.set(false);
        this.router.navigate(['/home']);
      },
      error: () => {
        this.loading.set(false);
        this.code.set('');
        this.step.set('create-code');
        this.errorMessage.set("Impossible d'enregistrer le nouveau code pour le moment.");
      },
    });
  }

  private submitLogin(): void {
    this.loading.set(true);
    this.auth.login(this.email.trim(), this.code()).subscribe({
      next: (res) => {
        this.loading.set(false);
        if (res.user.mustResetCode) {
          // Code provisoire accepté : obligation de le remplacer avant d'entrer.
          this.resetMode.set(true);
          this.code.set('');
          this.errorMessage.set('');
          this.infoMessage.set('');
          this.step.set('create-code');
          return;
        }
        this.router.navigate(['/home']);
      },
      error: () => {
        this.loading.set(false);
        this.code.set('');
        this.errorMessage.set('Code incorrect.');
      },
    });
  }

  forgotCode(): void {
    if (this.loading()) return;
    this.loading.set(true);
    this.errorMessage.set('');
    this.infoMessage.set('');

    this.auth.forgotCode(this.email.trim()).subscribe({
      next: () => {
        this.loading.set(false);
        this.code.set('');
        this.infoMessage.set(
          'Un code provisoire a été défini pour ce compte. Entrez-le pour continuer.'
        );
      },
      error: () => {
        this.loading.set(false);
        this.errorMessage.set("Impossible de réinitialiser le code pour cet email.");
      },
    });
  }
}
